-- The on-device voices are offered in the demo too: the Privacy Policy and Help say so.
-- Same text as src/data/legalPages.json; each change checks what's stored first.

do $migration$
declare s text;
begin
  select sections::text into s from public.legal_pages where slug = 'privacy' for update;
  if strpos(s, $lw$"Reading aloud with a voice on your device: for books in English, members, and anyone trying the demo, can choose from 39 natural voices that run in your own browser, with American, British, Scottish, Irish, Canadian, Australian, New Zealand and South African accents (women's, men's and a non-binary voice). A voice, about 63 to 77 MB, downloads once from our own storage (Supabase) and is kept in your browser. The text it reads never leaves your device, and nothing about your listening is sent to us or anyone else, so Kids profiles can use them too."$lw$) > 0 then return; end if;
  if strpos(s, $lw$"Reading aloud with a voice on your device: for books in English, members can choose from 39 natural voices that run in your own browser, with American, British, Scottish, Irish, Canadian, Australian, New Zealand and South African accents (women's, men's and a non-binary voice). A voice, about 63 to 77 MB, downloads once from our own storage (Supabase) and is kept in your browser. The text it reads never leaves your device, and nothing about your listening is sent to us or anyone else, so Kids profiles can use them too."$lw$) = 0 then raise exception 'demo voices: the privacy paragraph was not found as stored'; end if;
  update public.legal_pages set sections = replace(s, $lw$"Reading aloud with a voice on your device: for books in English, members can choose from 39 natural voices that run in your own browser, with American, British, Scottish, Irish, Canadian, Australian, New Zealand and South African accents (women's, men's and a non-binary voice). A voice, about 63 to 77 MB, downloads once from our own storage (Supabase) and is kept in your browser. The text it reads never leaves your device, and nothing about your listening is sent to us or anyone else, so Kids profiles can use them too."$lw$, $lw$"Reading aloud with a voice on your device: for books in English, members, and anyone trying the demo, can choose from 39 natural voices that run in your own browser, with American, British, Scottish, Irish, Canadian, Australian, New Zealand and South African accents (women's, men's and a non-binary voice). A voice, about 63 to 77 MB, downloads once from our own storage (Supabase) and is kept in your browser. The text it reads never leaves your device, and nothing about your listening is sent to us or anyone else, so Kids profiles can use them too."$lw$)::jsonb where slug = 'privacy';
end
$migration$;

